 $subject='Změna stavu objednávky '.$order['order_number'].' | KupSiApku';$encoded='=?UTF-8?B?'.base64_encode($subject).'?=';$name=trim($order['customer_first_name'].' '.$order['customer_last_name']);$extra=$to==='paid'?"\nZakoupené aplikace byly zpřístupněny ve Vašem účtu.\n":($to==='refunded'?"\nPřístup udělený touto objednávkou byl ukončen. Vaše uložená data nebyla automaticky smazána.\n":'');$message="Dobrý den {$name},\n\nstav Vaší objednávky {$order['order_number']} byl změněn.\n\nNový stav: {$label}\n{$extra}\nPřehled objednávek:\n{$appUrl}/objednavky.html\n\nDěkujeme.\nKupSiApku.cz\n{$appUrl}\n";$sent=@mail($order['customer_email'],$encoded,$message,$headers);
